{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.RAR_WH_PRODUCT_MARKETING_CONSOLIDATED AS WITH sales AS ( SELECT DISTINCT order_date, CAST(product_id AS STRING) AS product_id, SKU, CAST(PRODUCT_NAME_FINAL AS STRING) AS PRODUCT_NAME_FINAL, SUM(IFNULL(selling_price,0)) AS sales FROM `maplemonk.rainandrainbow_wh_SALES_CONSOLIDATED` GROUP BY 1,2,3,4 ), sku_map AS ( SELECT * FROM `rainandrainbow-wh.maplemonk.RAR_unicommerce_get_product_listing` WHERE mrp IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY channel_product_id ORDER BY DATE(updated) DESC) = 1 ), marketing_consolidated AS ( SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.rainandrainbow_wh_MARKETING_CONSOLIDATED` GROUP BY 1,2 ), product_master AS ( SELECT DISTINCT product_code, name, category_name FROM rainandrainbow-wh.maplemonk.RAR_unicommerce_get_product_master QUALIFY ROW_NUMBER() OVER (PARTITION BY product_code ORDER BY DATE(updated) DESC) = 1 ), facebook AS ( SELECT CAST(fc.Adset_Name AS STRING) AS ADSET_NAME, CAST(fc.Adset_ID AS STRING) AS ADSET_ID, CAST(fc.ad_id AS STRING) AS AD_ID, CAST(fc.ad_name AS STRING) AS AD_NAME, CAST(fc.Account_NAME AS STRING) AS ACCOUNT_NAME, CAST(fc.Account_ID AS STRING) AS ACCOUNT_ID, CAST(fc.Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(fc.Campaign_ID AS STRING) AS CAMPAIGN_ID, CAST(fc.product_id AS STRING) AS PRODUCT_ID, CAST(NULL AS STRING) AS VARIANT_ID, DATE(fc.Date) AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', DATE(fc.Date)) AS DAY_OF_WEEK, EXTRACT(YEAR FROM DATE(fc.Date)) AS YEAR, EXTRACT(MONTH FROM DATE(fc.Date)) AS MONTH, CAST(fc.Channel AS STRING) AS CHANNEL, CAST(fc.Account AS STRING) AS ACCOUNT, SUM(CAST(fc.Clicks AS FLOAT64)) AS CLICKS, SUM(CAST(fc.Spend AS FLOAT64)) AS SPEND, SUM(CAST(fc.Impressions AS FLOAT64)) AS IMPRESSIONS, SUM(CAST(fc.Conversions AS FLOAT64)) AS CONVERSIONS, SUM(CAST(fc.Conversion_Value AS FLOAT64)) AS CONVERSION_VALUE, SUM(IFNULL(sl.sales,0)) AS SALES, COALESCE(LOWER(TRIM(sm.sku_code)), LOWER(TRIM(sl.sku))) AS SKU FROM maplemonk.RAR_Wh_Product_FACEBOOK_CONSOLIDATED fc LEFT JOIN sku_map sm ON TRIM(LOWER(CAST(fc.product_id AS STRING))) = TRIM(LOWER(CAST(sm.channel_product_id AS STRING))) LEFT JOIN sales sl ON TRIM(LOWER(CAST(fc.product_id AS STRING))) = TRIM(LOWER(CAST(sl.product_id AS STRING))) GROUP BY ALL ), google AS ( SELECT CAST(gc.ADSET_NAME AS STRING) AS ADSET_NAME, CAST(gc.ADSET_ID AS STRING) AS ADSET_ID, CAST(gc.AD_ID AS STRING) AS AD_ID, CAST(gc.AD_NAME AS STRING) AS AD_NAME, CAST(gc.ACCOUNT_NAME AS STRING) AS ACCOUNT_NAME, CAST(gc.ACCOUNT_ID AS STRING) AS ACCOUNT_ID, CAST(gc.CAMPAIGN_NAME AS STRING) AS CAMPAIGN_NAME, CAST(gc.CAMPAIGN_ID AS STRING) AS CAMPAIGN_ID, CAST(SPLIT(gc.product_id, \'_\')[SAFE_OFFSET(2)] AS STRING) AS PRODUCT_ID, CAST(SPLIT(gc.product_id, \'_\')[SAFE_OFFSET(3)] AS STRING) AS VARIANT_ID, DATE(gc.Date) AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', DATE(gc.Date)) AS DAY_OF_WEEK, EXTRACT(YEAR FROM DATE(gc.Date)) AS YEAR, EXTRACT(MONTH FROM DATE(gc.Date)) AS MONTH, CAST(gc.Channel AS STRING) AS CHANNEL, CAST(gc.Account AS STRING) AS ACCOUNT, SUM(CAST(gc.clicks AS FLOAT64)) AS CLICKS, SUM(CAST(gc.spend AS FLOAT64)) AS SPEND, SUM(CAST(gc.Impressions AS FLOAT64)) AS IMPRESSIONS, SUM(CAST(gc.Conversions AS FLOAT64)) AS CONVERSIONS, SUM(CAST(gc.Conversion_Value AS FLOAT64)) AS CONVERSION_VALUE, SUM(IFNULL(sl.sales,0)) AS SALES, COALESCE(LOWER(TRIM(sm.sku_code)), LOWER(TRIM(sl.sku))) AS SKU FROM maplemonk.RAR_wh_Product_GOOGLEADS_CONSOLIDATED gc LEFT JOIN sku_map sm ON TRIM(LOWER(CAST(SPLIT(gc.product_ID, \'_\')[SAFE_OFFSET(2)] AS STRING))) = TRIM(LOWER(CAST(sm.channel_product_id AS STRING))) LEFT JOIN sales sl ON TRIM(LOWER(CAST(SPLIT(gc.product_ID, \'_\')[SAFE_OFFSET(2)] AS STRING))) = TRIM(LOWER(CAST(sl.product_id AS STRING))) GROUP BY ALL ), flipkart AS ( SELECT CAST(fk.Adset_Name AS STRING) AS ADSET_NAME, CAST(fk.Adset_ID AS STRING) AS ADSET_ID, CAST(fk.ad_id AS STRING) AS AD_ID, CAST(fk.ad_name AS STRING) AS AD_NAME, CAST(fk.Account_Name AS STRING) AS ACCOUNT_NAME, CAST(fk.Account_ID AS STRING) AS ACCOUNT_ID, CAST(fk.Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(fk.Campaign_ID AS STRING) AS CAMPAIGN_ID, CAST(fk.product_id AS STRING) AS PRODUCT_ID, CAST(NULL AS STRING) AS VARIANT_ID, fk.DATE AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', fk.Date) AS DAY_OF_WEEK, EXTRACT(YEAR FROM fk.Date) AS YEAR, EXTRACT(MONTH FROM fk.Date) AS MONTH, CAST(fk.Channel AS STRING) AS CHANNEL, CAST(fk.Account AS STRING) AS ACCOUNT, SUM(CAST(fk.Clicks AS FLOAT64)) AS CLICKS, SUM(CAST(fk.Spend AS FLOAT64)) AS SPEND, SUM(CAST(fk.Impressions AS FLOAT64)) AS IMPRESSIONS, SUM(CAST(fk.Conversions AS FLOAT64)) AS CONVERSIONS, SUM(CAST(fk.Conversion_Value AS FLOAT64)) AS CONVERSION_VALUE, SUM(CAST(fk.SALES AS FLOAT64)) AS SALES, LOWER(TRIM(fk.sku)) AS SKU FROM maplemonk.RAR_wh_Product_Flipkart_FSN fk GROUP BY ALL ), marketing_consolidated_product_intermediate AS ( SELECT * FROM facebook UNION ALL SELECT * FROM google UNION ALL SELECT * FROM flipkart ) SELECT m.*, COALESCE(UPPER(pm.name), UPPER(sl.product_name_final)) AS PRODUCT_NAME, UPPER(CAST(pm.CATEGORY_name AS STRING)) AS PRODUCT_CATEGORY, IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS total_product_lvl_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN NULL ELSE mc.total_channel_spend END, 0) AS total_channel_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN NULL ELSE mc.total_channel_spend END, 0) - IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS spend_diff, CASE WHEN SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL) != 0 THEN ((CASE WHEN LOWER(m.channel) = \'amazon\' THEN NULL ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.SALES / SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE 0 END AS allocated_spend_diff, CASE WHEN SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL) != 0 THEN m.SPEND + ((CASE WHEN LOWER(m.channel) = \'amazon\' THEN NULL ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.SALES / SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE SPEND END AS corrected_spend FROM marketing_consolidated_product_intermediate m LEFT JOIN marketing_consolidated mc ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(mc.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(mc.date AS DATE) LEFT JOIN product_master pm ON REGEXP_REPLACE(LOWER(pm.product_code), r\'[^a-z0-9]\', \'\') = REGEXP_REPLACE(LOWER(m.sku), r\'[^a-z0-9]\', \'\') LEFT JOIN sales sl ON REGEXP_REPLACE(LOWER(sl.sku), r\'[^a-z0-9]\', \'\') = REGEXP_REPLACE(LOWER(m.sku), r\'[^a-z0-9]\', \'\') ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            